package com.example.rokidkeyboardbridge;
import android.graphics.*;import android.view.View;import java.io.InputStream;
/** Cached corrected rest artwork; finite keyframes, small breathing/blink mesh and fixed-body facial patches. */
final class RestArtworkRenderer {
 static final String MASTER="loki_rest_master_v675.png",MOTION="loki_rest_motion_v675.png",FACES="loki_rest_faces_v675.png",WAVE="loki_rest_wave_v675.png",KNEE="loki_rest_knee_v676.png",CONVERSATION="loki_rest_conversation_faces_v677.png";
 private int reactionKind,reactionDirection;private long reactionAge;void reaction(int kind,int direction,long age){reactionKind=kind;reactionDirection=direction;reactionAge=age;}
 private final View host;private Bitmap[] bodies,faces,kneeFaces;private boolean loading;private int generation;private long retryAfter;
 private final Paint paint=new Paint(3);private final float[] mesh=new float[17*33*2],faceMesh=new float[13*13*2];private final float[] fidgetBase=new float[17*33*2];private int activeMotion;private long activeAge;private int face,previousFace;private long faceAt;
 private ComfortPoseRenderer comfort;private ComfortPoseRenderer comfort(){if(comfort==null)comfort=new ComfortPoseRenderer(host);return comfort;}
 boolean readyForMotion(int motion){return ComfortPoseIntent.active(motion)?comfort!=null&&comfort.ready(motion-8):ready();}
 void request(int motion){if(ComfortPoseIntent.active(motion))comfort().request(motion-8);else request();}
 RestArtworkRenderer(View host){this.host=host;}
 boolean ready(){return bodies!=null&&faces!=null;}
 private Bitmap decode(String name,int sample)throws Exception{try(InputStream in=host.getContext().getAssets().open(name)){BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=sample;o.inPreferredConfig=Bitmap.Config.ARGB_8888;Bitmap b=BitmapFactory.decodeStream(in,null,o);if(b==null)throw new IllegalStateException("Missing rest artwork");return b;}}
 private static void recycle(Bitmap[] bitmaps){if(bitmaps!=null)for(Bitmap b:bitmaps)if(b!=null&&!b.isRecycled())b.recycle();}
 void request(){if(ready()||loading||android.os.SystemClock.uptimeMillis()<retryAfter)return;loading=true;final int token=generation;
 new Thread(()->{Bitmap[] b=new Bitmap[18],f=new Bitmap[10],k=new Bitmap[4];Bitmap atlas=null;try{b[9]=decode(MASTER,2);int[] box=RestArtworkLayout.face(0);f[0]=Bitmap.createBitmap(b[9],box[0],box[1],box[2]-box[0],box[3]-box[1]);atlas=decode(MOTION,1);for(int i=0;i<9;i++){int[] box2=RestArtworkLayout.bounds(i);b[i]=Bitmap.createBitmap(atlas,box2[0],box2[1],box2[2],box2[3]);}atlas.recycle();atlas=decode(WAVE,1);for(int i=0;i<4;i++){int[] box2=RestArtworkLayout.bounds(10+i);b[10+i]=Bitmap.createBitmap(atlas,box2[0],box2[1],box2[2],box2[3]);}f[5]=Bitmap.createBitmap(b[10],252,60,60,56);atlas.recycle();atlas=decode(FACES,1);for(int i=0;i<4;i++){int w=atlas.getWidth()/2;box=RestArtworkLayout.face(i+1);f[i+1]=Bitmap.createBitmap(atlas,(i%2)*w+box[0],(i/2)*747+box[1],box[2]-box[0],box[3]-box[1]);}
 atlas.recycle();atlas=decode(KNEE,1);for(int i=0;i<4;i++){int[] bounds=RestArtworkLayout.bounds(14+i);b[14+i]=Bitmap.createBitmap(atlas,bounds[0],bounds[1],bounds[2],bounds[3]);bounds=RestArtworkLayout.kneeFace(14+i);k[i]=Bitmap.createBitmap(b[14+i],bounds[0],bounds[1],60,56);}
 atlas.recycle();atlas=decode(CONVERSATION,1);for(int i=0;i<4;i++){int x=(i%2)*512+(i%2==0?244:214),y=(i/2)*735+(i<2?50:64);f[6+i]=Bitmap.createBitmap(atlas,x,y,60,56);}
 }catch(Exception|OutOfMemoryError e){recycle(b);recycle(f);recycle(k);b=null;f=null;android.util.Log.w("LokiRestArtwork","Rest artwork decode failed",e);}finally{if(atlas!=null&&!atlas.isRecycled())atlas.recycle();}
 final Bitmap[] loadedBodies=b,loadedFaces=f,loadedKnee=k;host.post(()->{if(token!=generation){recycle(loadedBodies);recycle(loadedFaces);recycle(loadedKnee);return;}loading=false;bodies=loadedBodies;faces=loadedFaces;kneeFaces=loadedKnee;retryAfter=ready()?0:android.os.SystemClock.uptimeMillis()+60000;host.invalidate();});},"LokiRestArtworkDecode").start();}
 boolean draw(Canvas canvas,int width,int height,int motion,int expression,long age,long now,boolean speaking){if(ComfortPoseIntent.active(motion))return comfort().draw(canvas,width,height,motion-8,expression,age,now,speaking,reactionKind,reactionAge);request();if(!ready()||width<=0||height<=0)return false;age=CharacterMotionTuning.time(age);activeMotion=motion;activeAge=age;expression=Math.max(0,Math.min(9,expression));if(face!=expression||now<faceAt){previousFace=face;face=expression;faceAt=now;}int current=RestAnimationTimeline.frame(motion,age),previous=RestAnimationTimeline.previous(motion,age);float mix=RestAnimationTimeline.mix(motion,age);int save=canvas.save();canvas.clipRect(0,0,width,height);if(mix<1&&previous!=current)drawFrame(canvas,width,height,previous,1-mix,now,speaking);drawFrame(canvas,width,height,current,previous==current?1:mix,now,speaking);canvas.restoreToCount(save);return true;}
 private void drawFrame(Canvas canvas,int width,int height,int key,float alpha,long now,boolean speaking){if(alpha<=0)return;Bitmap b=bodies[key];float x=RestArtworkLayout.coordinate(key,0,b.getWidth(),b.getHeight()),top=RestArtworkLayout.coordinate(key,1,b.getWidth(),b.getHeight()),floor=RestArtworkLayout.coordinate(key,2,b.getWidth(),b.getHeight()),span=RestArtworkLayout.coordinate(key,3,b.getWidth(),b.getHeight());float scale=CharacterViewport.scale(RestArtworkLayout.stature(key,b.getHeight()),width,height);int save=canvas.save();canvas.translate(width*.5f-x*scale,CharacterViewport.top(height*.96f-floor*scale,top,scale,height));canvas.scale(scale,scale);int n=0;for(int row=0;row<=32;row++)for(int col=0;col<=16;col++){mesh[n++]=b.getWidth()*col/16f;mesh[n++]=b.getHeight()*row/32f;}GestureMicroMotion.apply(mesh,16,32,b.getWidth(),b.getHeight(),x,top,floor,now,CharacterMotionTuning.scale()*CharacterMotionTuning.body());if(key>=14&&activeMotion==7&&activeAge<ShyFidgetMotion.DURATION){float gain=Math.min(1,CharacterMotionTuning.scale()*CharacterMotionTuning.body());if(gain>0){System.arraycopy(mesh,0,fidgetBase,0,mesh.length);ShyFidgetMotion.apply(mesh,16,32,b.getWidth(),b.getHeight(),x,top+95,60,80,activeAge);for(int i=0;i<mesh.length;i++)mesh[i]=fidgetBase[i]+(mesh[i]-fidgetBase[i])*gain;}}
 if(key==RestAnimationTimeline.MASTER||key>=14)RestInteractionMotion.apply(mesh,16,32,b.getWidth(),b.getHeight(),x,top+95,reactionKind,reactionDirection,reactionAge,CharacterMotionTuning.scale()*CharacterMotionTuning.body());
 paint.setAlpha(Math.round(255*alpha));canvas.drawBitmapMesh(b,16,32,mesh,0,null,0,paint);
 if(key==RestAnimationTimeline.MASTER||key>=14){float progress=Math.min(1,Math.max(0,now-faceAt)/260f);if(previousFace!=face&&progress<1)drawFace(canvas,key,previousFace,alpha*(1-progress),now,speaking);drawFace(canvas,key,face,alpha*(previousFace==face?1:progress),now,speaking);}canvas.restoreToCount(save);}
 private void drawFace(Canvas canvas,int key,int selected,float alpha,long now,boolean speaking){if(alpha<=0)return;Bitmap b=key>=14&&selected==0?kneeFaces[key-14]:faces[selected];float x=228,y=46,w=60,h=56;if(key>=14){x=RestArtworkLayout.coordinate(key,0,bodies[key].getWidth(),bodies[key].getHeight())-27;y=key<16?62:67;}long t=Math.max(0,now)%4700;float blink=t<280?Math.max(.12f,Math.abs(t-140)/140f):1;float blinkGain=(1-blink)*CharacterMotionTuning.eyes();int n=0;for(int row=0;row<=12;row++)for(int col=0;col<=12;col++){float u=col/12f,v=row/12f,dy=0;for(int eye=0;eye<2;eye++){float ex=eye==0?.35f:.73f,dx=(u-ex)/.16f,ey=(v-.35f)/.12f,weight=Math.max(0,1-dx*dx-ey*ey);dy-=(v-.35f)*blinkGain*weight;}if(speaking&&selected!=1){float dx=(u-.54f)/.2f,ey=(v-.78f)/.12f;dy+=(v-.78f)*.18f*(.5f+.5f*(float)Math.sin(now/100.0))*Math.max(0,1-dx*dx-ey*ey)*CharacterMotionTuning.face();}faceMesh[n++]=x+u*w;faceMesh[n++]=y+(v+dy)*h;}paint.setAlpha(Math.round(255*alpha));canvas.drawBitmapMesh(b,12,12,faceMesh,0,null,0,paint);}
 void release(){if(comfort!=null){comfort.release();comfort=null;}generation++;loading=false;recycle(bodies);recycle(faces);recycle(kneeFaces);bodies=faces=kneeFaces=null;}
}
